use clap::{Arg, ArgAction, Command};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

// ---------- logging ----------
static mut LOG_LEVEL: u8 = 0;

fn set_log_level(v: u8) {
    unsafe { LOG_LEVEL = v; }
}
fn get_log_level() -> u8 {
    unsafe { LOG_LEVEL }
}
fn log_enabled(level: &str) -> bool {
    let cur = get_log_level();
    match level {
        "ERROR" => true,
        "WARN" => cur <= 0 || true, // warn always? actually level 0 = warn, so warn+error shown
        "INFO" => cur >= 1,
        "DEBUG" => cur >= 2,
        "TRACE" => cur >= 3,
        _ => false,
    }
}
// warn logic: at level 0, show WARN and ERROR; at 1 show INFO too, etc.
fn should_log(level: &str) -> bool {
    let cur = get_log_level();
    match level {
        "ERROR" => true,
        "WARN" => true, // always show warn? original default 0 warn shows warn+error
        "INFO" => cur >= 1,
        "DEBUG" => cur >= 2,
        "TRACE" => cur >= 3,
        _ => false,
    }
}

fn log_msg(level: &str, target: &str, msg: &str) {
    if !should_log(level) {
        return;
    }
    let now = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string();
    // pad level to 5 chars like env_logger: INFO has extra space? Actually format is "{level:>5}"? Let's mimic: ERROR (5), WARN (4+1?), INFO (4+1?), DEBUG, TRACE
    // Observed: "[... INFO  marmite::site]" (two spaces after INFO), "[... ERROR marmite]" (one space)
    // That's because level padded to 5: "INFO " + " " separator? Let's just format as env_logger does: format!("{:>5}", level) then space?
    // env_logger default: "[timestamp LEVEL target]" where LEVEL is padded? We'll do: level padded to 5 left? Actually "INFO " is 5 chars (INFO+space), "ERROR" is 5, "WARN " is 5, "DEBUG" 5, "TRACE" 5.
    // Then one space before target. So INFO -> " INFO " (with leading space?) Hmm.
    // Simpler: replicate observed: for INFO, two spaces after; for ERROR, one space. That's consistent with padding to 5 then one space: "INFO " (5) + " " = two spaces? No, "INFO" (4) padded to 5 = "INFO " (one trailing space), plus separator space = two spaces total. "ERROR" (5) + " " = one space. Yes!
    let padded = format!("{:>5}", level);
    eprintln!("[{} {} {}] {}", now, padded, target, msg);
}

macro_rules! log_info {
    ($target:expr, $($arg:tt)*) => {
        log_msg("INFO", $target, &format!($($arg)*))
    };
}
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => {
        log_msg("ERROR", $target, &format!($($arg)*))
    };
}
macro_rules! log_warn {
    ($target:expr, $($arg:tt)*) => {
        log_msg("WARN", $target, &format!($($arg)*))
    };
}
macro_rules! log_debug {
    ($target:expr, $($arg:tt)*) => {
        log_msg("DEBUG", $target, &format!($($arg)*))
    };
}

