        cfg.extra = Some(serde_json::Value::Object(map));
    }
    if let Some(v) = m.get_one::<bool>("toc") { cfg.toc = *v; }
    if let Some(v) = m.get_one::<bool>("json-feed") { cfg.json_feed = *v; }
    if let Some(v) = m.get_one::<bool>("show-next-prev-links") { cfg.show_next_prev_links = *v; }
    if let Some(v) = m.get_one::<bool>("publish-md") { cfg.publish_md = *v; }
    if let Some(v) = m.get_one::<String>("source-repository") { cfg.source_repository = Some(v.clone()); }
    if let Some(v) = m.get_one::<String>("image-provider") { cfg.image_provider = Some(v.clone()); }
    if let Some(v) = m.get_one::<String>("theme") { cfg.theme = Some(v.clone()); }
    if let Some(v) = m.get_one::<bool>("build-sitemap") { cfg.build_sitemap = *v; }
    if let Some(v) = m.get_one::<bool>("publish-urls-json") { cfg.publish_urls_json = *v; }
    if let Some(v) = m.get_one::<bool>("enable-shortcodes") { cfg.enable_shortcodes = *v; }
    if let Some(v) = m.get_one::<String>("shortcode-pattern") { cfg.shortcode_pattern = Some(v.clone()); }
    if let Some(v) = m.get_one::<bool>("skip-image-resize") { cfg.skip_image_resize = *v; }
}
