fn parse_frontmatter(file_content: &str) -> (HashMap<String, serde_yaml::Value>, String) {
    let trimmed = file_content.trim_start();
    if trimmed.starts_with("---") {
        // find second ---
        let mut lines = file_content.lines();
        let first = lines.next().unwrap_or("");
        if first.trim() == "---" {
            let mut fm_lines: Vec<String> = Vec::new();
            let mut rest_start: Option<usize> = None;
            let mut pos = first.len() + 1; // after first line + newline (approx)
            // More robust: search for \n---\n
            // Find second delimiter
            let content_after_first = &file_content[first.len()+1..];
            // handle \r\n?
            let mut found = None;
            for (i, line) in content_after_first.lines().enumerate() {
                if line.trim() == "---" {
                    found = Some(i);
                    break;
                }
            }
            if let Some(idx) = found {
                // collect fm lines up to idx
                let all_lines: Vec<&str> = content_after_first.lines().collect();
                let fm_str = all_lines[..idx].join("\n");
                let rest = all_lines[idx+1..].join("\n");
                // parse yaml
                let map: HashMap<String, serde_yaml::Value> = serde_yaml::from_str(&fm_str).unwrap_or_default();
                return (map, rest);
            }
        }
    }
    (HashMap::new(), file_content.to_string())
}

fn yaml_to_string(v: Option<&serde_yaml::Value>) -> String {
    match v {
        None => String::new(),
        Some(serde_yaml::Value::String(s)) => s.clone(),
        Some(serde_yaml::Value::Number(n)) => n.to_string(),
        Some(serde_yaml::Value::Bool(b)) => b.to_string(),
        Some(serde_yaml::Value::Null) => String::new(),
        Some(other) => {
            // for sequences etc, convert via json?
            format!("{:?}", other)
        }
    }
}

fn yaml_to_vec_string(v: Option<&serde_yaml::Value>) -> Vec<String> {
    match v {
        None => vec![],
        Some(serde_yaml::Value::String(s)) => {
            // comma separated?
            if s.contains(',') {
                s.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect()
            } else if s.is_empty() {
                vec![]
            } else {
                vec![s.trim().to_string()]
            }
        }
        Some(serde_yaml::Value::Sequence(seq)) => {
            seq.iter().map(|x| match x {
                serde_yaml::Value::String(s) => s.clone(),
                serde_yaml::Value::Number(n) => n.to_string(),
                _ => String::new(),
            }).filter(|x| !x.is_empty()).collect()
        }
        Some(serde_yaml::Value::Null) => vec![],
        _ => vec![],
    }
}

fn parse_date_value(v: Option<&serde_yaml::Value>) -> Option<chrono::DateTime<chrono::FixedOffset>> {
    let s = match v {
        None => return None,
        Some(serde_yaml::Value::String(s)) => s.clone(),
        Some(serde_yaml::Value::Number(n)) => n.to_string(),
        _ => return None,
    };
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    // try multiple formats
    // 2024-01-15, 2024-01-15 10:30:00, 2024-01-15T10:30:00+00:00, etc.
    let formats = [
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%dT%H:%M:%S%:z",
        "%Y-%m-%d %H:%M:%S %z",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%d-%m-%Y",
        "%b %e, %Y",
        "%B %e, %Y",
    ];
    for fmt in &formats {
        if let Ok(nd) = chrono::NaiveDate::parse_from_str(s, fmt) {
            let dt = nd.and_hms_opt(0,0,0).unwrap();
            let offset = chrono::FixedOffset::east_opt(0).unwrap();
            return Some(chrono::DateTime::from_naive_utc_and_offset(dt, offset));
        }
        if let Ok(ndt) = chrono::NaiveDateTime::parse_from_str(s, fmt) {
            let offset = chrono::FixedOffset::east_opt(0).unwrap();
            return Some(chrono::DateTime::from_naive_utc_and_offset(ndt, offset));
        }
        if let Ok(dt) = chrono::DateTime::parse_from_str(s, fmt) {
            return Some(dt);
        }
    }
    // try RFC3339
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(s) {
        return Some(dt.into());
    }
    None
}

fn extract_date_from_filename(fname: &str) -> Option<chrono::DateTime<chrono::FixedOffset>> {
    // match YYYY-MM-DD prefix
    if fname.len() >= 10 {
        let prefix = &fname[..10];
        if let Ok(nd) = chrono::NaiveDate::parse_from_str(prefix, "%Y-%m-%d") {
            let dt = nd.and_hms_opt(0,0,0).unwrap();
            let offset = chrono::FixedOffset::east_opt(0).unwrap();
            return Some(chrono::DateTime::from_naive_utc_and_offset(dt, offset));
        }
        // also YYYY-MM-DD-... with time? filename like 2026-09-04-15-44-09-slug? date part is first 10
    }
    None
}

fn strip_date_prefix(fname: &str) -> String {
    // remove YYYY-MM-DD- or YYYY-MM-DD-HH-MM-SS- prefix for slug generation
    // patterns: YYYY-MM-DD-xxx, YYYY-MM-DD-HH-MM-SS-xxx
    let mut s = fname.to_string();
    // remove .md extension first? caller handles
    // check for date prefix
    if s.len() > 11 {
        // check YYYY-MM-DD-
        let prefix = s[..10].to_string();
        if chrono::NaiveDate::parse_from_str(&prefix, "%Y-%m-%d").is_ok() {
            if s.chars().nth(10) == Some('-') {
                let rest = s[11..].to_string();
                // check if rest starts with HH-MM-SS- ?
                if rest.len() > 9 {
                    let time_part = rest[..8].to_string();
                    // HH-MM-SS with dashes?
                    let parts: Vec<&str> = time_part.split('-').collect();
                    if parts.len() == 3 && parts.iter().all(|p| p.len()==2 && p.chars().all(|c| c.is_ascii_digit())) {
                        if rest.len() > 9 && rest.chars().nth(8) == Some('-') {
                            return rest[9..].to_string();
                        }
                    }
                }
                return rest;
            }
        }
    }
    s
}

