                out.push_str(&format!("<code>{}</code>", escape_html(&code)));
                i = end + 1;
                continue;
            }
        }
        // bold ** or __
        if i+1 < chars.len() && ((chars[i]=='*' && chars[i+1]=='*') || (chars[i]=='_' && chars[i+1]=='_')) {
            let delim = chars[i];
            // find closing
            let mut j = i+2;
            let mut found = None;
            while j+1 < chars.len() {
                if chars[j]==delim && chars[j+1]==delim {
                    found = Some(j);
                    break;
                }
                j+=1;
            }
            if let Some(end) = found {
                let inner: String = chars[i+2..end].iter().collect();
                out.push_str(&format!("<strong>{}</strong>", render_inline(&inner)));
                i = end+2;
                continue;
            }
        }
        // strikethrough ~~
        if i+1 < chars.len() && chars[i]=='~' && chars[i+1]=='~' {
            let mut j = i+2;
            let mut found = None;
            while j+1 < chars.len() {
                if chars[j]=='~' && chars[j+1]=='~' {
                    found = Some(j);
                    break;
                }
                j+=1;
            }
            if let Some(end) = found {
                let inner: String = chars[i+2..end].iter().collect();
                out.push_str(&format!("<del>{}</del>", render_inline(&inner)));
                i = end+2;
                continue;
            }
        }
        // italic * or _
        if chars[i]=='*' || chars[i]=='_' {
            let delim = chars[i];
            if let Some(end) = find_char(&chars, i+1, delim) {
                // avoid matching bold already handled? ensure not double
                // if next char also delim, skip (already handled bold)
                if end+1 < chars.len() && chars[end+1]==delim {
                    // part of bold? just output char
                    out.push_str(&escape_html(&chars[i].to_string()));
                    i+=1;
                    continue;
                }
                let inner: String = chars[i+1..end].iter().collect();
                // avoid empty
                if !inner.is_empty() {
                    out.push_str(&format!("<em>{}</em>", render_inline(&inner)));
                    i = end+1;
                    continue;
                }
            }
        }
        // regular char: escape
        match chars[i] {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            c => out.push(c),
        }
        i+=1;
    }
    out
}

fn find_closing(chars: &[char], start: usize, close: char) -> Option<usize> {
    for i in start..chars.len() {
        if chars[i]==close {
            // handle escaped? ignore
            return Some(i);
        }
        if chars[i]=='\n' {
            // for inline, don't cross newline for links? but allow
        }
    }
    None
}
fn find_char(chars: &[char], start: usize, target: char) -> Option<usize> {
    for i in start..chars.len() {
        if chars[i]==target {
            return Some(i);
        }
    }
    None
}

fn markdown_to_html(md: &str) -> String {
    let lines: Vec<&str> = md.lines().collect();
    let mut html = String::new();
    let mut i = 0;
    // collect footnotes definitions
    let mut footnotes: HashMap<String, String> = HashMap::new();
    // first pass: extract footnote defs [^label]: text
    let mut filtered: Vec<String> = Vec::new();
    for line in &lines {
        let t = line.trim();
        if t.starts_with("[^") {
            if let Some(pos) = t.find("]:") {
                let label = t[2..pos].to_string();
                let text = t[pos+2..].trim().to_string();
                footnotes.insert(label, text);
                continue;
            }
        }
        filtered.push(line.to_string());
    }
    let lines: Vec<&str> = filtered.iter().map(|s| s.as_str()).collect();
    let mut in_code_block = false;
    let mut code_lang = String::new();
    let mut code_buf: Vec<String> = Vec::new();
    let mut in_blockquote = false;
    let mut bq_buf: Vec<String> = Vec::new();
    let mut list_stack: Vec<(String, usize)> = Vec::new(); // (type, indent)

    // helper to flush paragraph/list etc.
    // We'll process line by line
    let mut para_buf: Vec<String> = Vec::new();
    let flush_para = |buf: &mut Vec<String>, html: &mut String| {
        if !buf.is_empty() {
            let text = buf.join(" ");
            let trimmed = text.trim();
            if !trimmed.is_empty() {
                // check if text is already html block? no
                html.push_str(&format!("<p>{}</p>\n", render_inline(trimmed)));
            }
            buf.clear();
        }
    };

    // For simplicity, handle tables, headings, hr, lists, etc.
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();
        // code block fence
        if trimmed.starts_with("```") {
            if !in_code_block {
                // flush para
                if !para_buf.is_empty() {
                    let text = para_buf.join(" ");
                    if !text.trim().is_empty() {
                        html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                    }
                    para_buf.clear();
                }
                in_code_block = true;
                code_lang = trimmed[3..].trim().to_string();
                code_buf.clear();
            } else {
                // end
                in_code_block = false;
                let code_text = code_buf.join("\n");
                let esc = escape_html(&code_text);
                if code_lang.is_empty() {
                    html.push_str(&format!("<pre><code>{}\n</code></pre>\n", esc));
                } else {
                    html.push_str(&format!("<pre><code class=\"language-{}\">{}\n</code></pre>\n", escape_attr(&code_lang), esc));
                }
                code_lang.clear();
            }
            i+=1;
            continue;
        }
        if in_code_block {
            code_buf.push(line.to_string());
            i+=1;
            continue;
        }
        // indented code? 4 spaces
        if line.starts_with("    ") && !line.trim().is_empty() {
            // check if previous was blank or start, treat as code? simplify: if para empty, treat as code block line
            // collect consecutive indented lines
            if para_buf.is_empty() {
                let mut code_lines: Vec<String> = Vec::new();
                while i < lines.len() && lines[i].starts_with("    ") {
                    code_lines.push(lines[i][4..].to_string());
                    i+=1;
                }
                // also handle single? original renders indented as code
                let code_text = code_lines.join("\n");
                html.push_str(&format!("<pre><code>{}\n</code></pre>\n", escape_html(&code_text)));
                continue;
            }
        }
        // blank line: flush para, close lists? keep lists open? close para
        if trimmed.is_empty() {
            if !para_buf.is_empty() {
                let text = para_buf.join(" ");
                if !text.trim().is_empty() {
                    html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                }
                para_buf.clear();
            }
            // close blockquote?
            if in_blockquote {
                // flush bq
                let inner = markdown_to_html(&bq_buf.join("\n"));
                // inner already has <p> etc, wrap in blockquote
                // But to match original: <blockquote>\n<p>quote</p>\n</blockquote>
                html.push_str(&format!("<blockquote>\n{}</blockquote>\n", inner));
                bq_buf.clear();
                in_blockquote = false;
            }
            i+=1;
            continue;
        }
        // hr: ---, ***, ___
        if trimmed=="---" || trimmed=="***" || trimmed=="___" || trimmed=="----" || (trimmed.chars().all(|c| c=='-'||c=='*'||c=='_') && trimmed.len()>=3) {
            if !para_buf.is_empty() {
                let text = para_buf.join(" ");
                html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                para_buf.clear();
            }
            // check if it's table separator? no, hr
            html.push_str("<hr />\n");
            i+=1;
            continue;
        }
        // heading
        if trimmed.starts_with('#') {
            let mut level = 0;
            for c in trimmed.chars() {
                if c=='#' { level+=1; } else { break; }
            }
            if level>=1 && level<=6 && trimmed[level..].starts_with(' ') || trimmed.len()==level {
                if !para_buf.is_empty() {
                    let text = para_buf.join(" ");
                    html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                    para_buf.clear();
                }
                let text = trimmed[level..].trim();
                let id = slugify_anchor(text);
                let inner = render_inline(text);
                html.push_str(&format!("<h{}><a href=\"#{}\" aria-hidden=\"true\" class=\"anchor\" id=\"{}\"></a>{}</h{}>\n", level, id, id, inner, level));
                i+=1;
                continue;
            }
        }
        // blockquote
        if trimmed.starts_with('>') {
            if !para_buf.is_empty() {
                let text = para_buf.join(" ");
                html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                para_buf.clear();
            }
            // collect consecutive bq lines
            bq_buf.clear();
            while i < lines.len() && lines[i].trim_start().starts_with('>') {
                let l = lines[i].trim_start();
                let content = l[1..].trim_start();
                // handle "> " vs ">"
                bq_buf.push(content.to_string());
                i+=1;
            }
            let inner = markdown_to_html(&bq_buf.join("\n"));
            html.push_str(&format!("<blockquote>\n{}</blockquote>\n", inner));
            continue;
        }
        // table: check if line contains | and next line is separator
        if trimmed.contains('|') && i+1 < lines.len() {
            let next = lines[i+1].trim();
            // separator like |---|---| or ---|--- etc
            let is_sep = next.contains("---") || next.contains(":---") || next.contains("---:");
            // more precise: line with only | - : spaces
            let sep_ok = !next.is_empty() && next.chars().all(|c| c=='|'||c=='-'||c==':'||c==' '||c=='\t');
            if is_sep && sep_ok {
                if !para_buf.is_empty() {
                    let text = para_buf.join(" ");
                    html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                    para_buf.clear();
                }
                // parse header
                let header_cells: Vec<String> = trimmed.split('|').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
                // skip separator
                i+=2;
                let mut rows: Vec<Vec<String>> = Vec::new();
                while i < lines.len() && lines[i].contains('|') && !lines[i].trim().is_empty() {
                    let row: Vec<String> = lines[i].split('|').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
                    if row.is_empty() { break; }
                    rows.push(row);
                    i+=1;
                }
                html.push_str("<table>\n<thead>\n<tr>\n");
                for h in &header_cells {
                    html.push_str(&format!("<th>{}</th>\n", render_inline(h)));
                }
                html.push_str("</tr>\n</thead>\n<tbody>\n");
                for r in &rows {
                    html.push_str("<tr>\n");
                    for c in r {
                        html.push_str(&format!("<td>{}</td>\n", render_inline(c)));
                    }
                    html.push_str("</tr>\n");
                }
                html.push_str("</tbody>\n</table>\n");
                continue;
            }
        }
        // list: - , *, +, 1. , task
        let lstripped = line.trim_start();
        let indent = line.len() - lstripped.len();
        let is_ul = lstripped.starts_with("- ") || lstripped.starts_with("* ") || lstripped.starts_with("+ ");
        let is_ol = {
            // check digit. pattern
            let mut chars = lstripped.chars();
            let mut num = String::new();
            for c in chars.by_ref() {
                if c.is_ascii_digit() { num.push(c); } else { break; }
            }
            if !num.is_empty() && lstripped[num.len()..].starts_with(". ") {
                true
            } else { false }
        };
        if is_ul || is_ol {
            if !para_buf.is_empty() {
                let text = para_buf.join(" ");
                html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
                para_buf.clear();
            }
            // collect list block
            let list_type = if is_ul { "ul" } else { "ol" };
            // gather consecutive list items with same or greater indent? simplify: collect until non-list
            let mut items: Vec<String> = Vec::new();
            let mut detected_type = list_type.to_string();
            while i < lines.len() {
                let l = lines[i];
                let t = l.trim_start();
                let ul = t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ");
                let ol = {
                    let mut num = String::new();
                    for c in t.chars() {
                        if c.is_ascii_digit() { num.push(c); } else { break; }
                    }
                    !num.is_empty() && t[num.len()..].starts_with(". ")
                };
                if !ul && !ol { break; }
                // determine content after marker
                let content = if ul {
                    t[2..].trim().to_string()
                } else {
                    // find ". "
                    if let Some(pos) = t.find(". ") {
                        t[pos+2..].trim().to_string()
                    } else { t.to_string() }
                };
                // check task list
                if content.starts_with("[x] ") || content.starts_with("[X] ") {
                    let inner = content[4..].trim();
                    items.push(format!("<li><input type=\"checkbox\" checked=\"\" disabled=\"\" /> {}</li>", render_inline(inner)));
                } else if content.starts_with("[ ] ") {
                    let inner = content[4..].trim();
                    items.push(format!("<li><input type=\"checkbox\" disabled=\"\" /> {}</li>", render_inline(inner)));
                } else {
                    items.push(format!("<li>{}</li>", render_inline(&content)));
                }
                // peek next: if next is indented continuation? ignore for now
                i+=1;
                // if next line is blank, break? but allow? check if next is list, continue
            }
            // decide ul vs ol based on first? if mixed, use first
            html.push_str(&format!("<{}>\n", detected_type));
            for it in items {
                html.push_str(&format!("{}\n", it));
            }
            html.push_str(&format!("</{}>\n", detected_type));
            continue;
        }
        // footnote definition already handled, footnote ref inline handled
        // regular paragraph line: accumulate
        para_buf.push(line.trim().to_string());
        i+=1;
    }
    // flush remaining
    if !para_buf.is_empty() {
        let text = para_buf.join(" ");
        if !text.trim().is_empty() {
            html.push_str(&format!("<p>{}</p>\n", render_inline(text.trim())));
        }
    }
    if in_blockquote && !bq_buf.is_empty() {
        let inner = markdown_to_html(&bq_buf.join("\n"));
        html.push_str(&format!("<blockquote>\n{}</blockquote>\n", inner));
    }
    // append footnotes section if any
    if !footnotes.is_empty() {
        html.push_str("<section class=\"footnotes\" data-footnotes>\n<ol>\n");
        // sort by label? original order? use sorted
        let mut keys: Vec<&String> = footnotes.keys().collect();
        keys.sort();
        for k in keys {
            let v = &footnotes[k];
            html.push_str(&format!("<li id=\"fn-{}\">\n<p>{} <a href=\"#fnref-{}\" class=\"footnote-backref\" data-footnote-backref data-footnote-backref-idx=\"1\" aria-label=\"Back to reference {}\">\u{21A9}</a></p>\n</li>\n", escape_attr(k), render_inline(v), escape_attr(k), escape_attr(k)));
        }
        html.push_str("</ol>\n</section>\n");
    }
    html
}
