fn render_rss(cfg: &Config, title: &str, link_suffix: &str, items: &[Content]) -> String {
    // link_suffix like "index", "tag-rust", etc. source url?
    let site_url = cfg.url.trim();
    let base = if site_url.is_empty() {
        "http://".to_string()
    } else {
        // ensure protocol? handle https flag?
        let mut u = site_url.to_string();
        if !u.starts_with("http://") && !u.starts_with("https://") {
            let use_https = cfg.https.unwrap_or(false);
            if use_https {
                u = format!("https://{}", u);
            } else {
                u = format!("http://{}", u);
            }
        }
        u
    };
    // pubDate: latest item date or now?
    let latest = items.iter().filter_map(|c| c.date).max();
    let pub_date = latest.map(|d| d.with_timezone(&chrono::Utc).format("%a, %d %b %Y %H:%M:%S GMT").to_string()).unwrap_or_else(|| chrono::Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string());
    let build_date = chrono::Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string();
    let mut rss = format!(r#"<?xml version="1.0" encoding="utf-8"?><rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/"><channel><title>{}</title><link>{}</link><description>{}</description><pubDate>{}</pubDate><lastBuildDate>{}</lastBuildDate><generator>marmite</generator>"#,
        escape_html(&cfg.name), escape_html(&base), escape_html(&cfg.tagline), pub_date, build_date
    );
    // sort items by date desc
    let mut sorted = items.to_vec();
    sorted.sort_by(|a,b| b.date.cmp(&a.date));
    for c in sorted {
        let link = format!("{}{}/{}.html", base, if base.ends_with('/') { "" } else { "/" }, c.slug);
        // Actually base already has protocol, need to avoid double slash: base is "http://" + ""? For empty url, base is "http://", then link is "http:///hello-world.html" (triple slash) as observed: "<link>http:///hello-world.html</link>"
        // Our format above gives base + "/" + slug: "http://" + "/" + "hello-world.html" = "http:///hello-world.html" correct.
        // For non-empty, base is "http://example.com", then + "/" + slug = correct.
        let cats: String = c.tags.iter().map(|t| format!("<category>{}</category>", escape_html(t))).collect();
        let desc = if c.description.is_empty() { format!("\"{}\"", " ") } else { format!("\"{}\"", escape_html(&c.description)) };
        // Original: <description><![CDATA["A test post"]]></description> with quotes and brackets? Actually observed: <![CDATA["A test post"]]>
        // For empty? Check page? For rss with description, it wraps in quotes? Let's replicate: if description empty, use excerpt? For now use description with quotes
        let desc_cdata = if c.description.is_empty() {
            let txt = strip_html(&c.html);
            format!("<![CDATA[\"{}\"]]>", escape_html(&txt.chars().take(200).collect::<String>()))
        } else {
            format!("<![CDATA[\"{}\"]]>", escape_html(&c.description))
        };
        let pubd = c.date.map(|d| d.with_timezone(&chrono::Utc).format("%a, %d %b %Y %H:%M:%S GMT").to_string()).unwrap_or_else(|| pub_date.clone());
        rss.push_str(&format!(r#"<item><title>{}</title><link>{}</link><description>{}</description>{}<guid>{}</guid><pubDate>{}</pubDate><source url="{}">{}</source><content:encoded><![CDATA[{}]]></content:encoded></item>"#,
            escape_html(&c.title), escape_html(&link), desc_cdata, cats, escape_html(&link), pubd, escape_html(&base), escape_html(link_suffix), c.html
        ));
    }
    rss.push_str("</channel></rss>");
    rss
}

fn render_sitemap(urls: &[String]) -> String {
    let mut s = String::from(r#"<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
"#);
    for u in urls {
        s.push_str(&format!("  <url>\n    <loc>{}</loc>\n  </url>\n", escape_html(u)));
    }
    s.push_str("</urlset>");
    s
}

