    custom_404: Option<String>,
}

fn sort_contents(mut v: Vec<Content>) -> Vec<Content> {
    v.sort_by(|a,b| {
        // pinned first?
        if a.pinned != b.pinned {
            return b.pinned.cmp(&a.pinned);
        }
        b.date.cmp(&a.date)
    });
    v
}

