fn render_json_feed(cfg: &Config, title: &str, feed_url: &str, items: &[Content]) -> String {
    let mut sorted = items.to_vec();
    sorted.sort_by(|a,b| b.date.cmp(&a.date));
    let mut jitems: Vec<serde_json::Value> = Vec::new();
    for c in sorted {
        let url = format!("/{}.html", c.slug);
        jitems.push(serde_json::json!({
            "id": url,
            "url": url,
            "title": c.title,
            "content_html": c.html,
            "summary": "",
            "date_published": c.date.map(|d| d.to_rfc3339()).unwrap_or_default().replace("+00:00", "-00:00"),
            "image": "",
            "authors": c.authors,
            "tags": c.tags,
            "language": if cfg.language.is_empty() { "en" } else { &cfg.language }
        }));
    }
    let feed = serde_json::json!({
        "version": "https://jsonfeed.org/version/1",
        "title": cfg.name,
        "home_page_url": cfg.url,
        "feed_url": feed_url,
        "description": cfg.tagline,
        "items": jitems
    });
    serde_json::to_string_pretty(&feed).unwrap()
}
