fn handle_new(input: &Path, title: &str, is_page: bool, tags: Option<&str>, edit: bool) {
    let slug = slugify(title);
    let (filename, content) = if is_page {
        let fname = format!("{}.md", slug);
        let body = if let Some(t) = tags {
            format!("---\ntags: {}\n---\n# {}\n", t, title)
        } else {
            format!("# {}\n", title)
        };
        (fname, body)
    } else {
        let now = chrono::Local::now();
        // Use UTC? Original filename uses local? We'll use Local
        let date_prefix = now.format("%Y-%m-%d-%H-%M-%S").to_string();
        let fname = format!("{}-{}.md", date_prefix, slug);
        let body = if let Some(t) = tags {
            format!("---\ntags: {}\n---\n# {}\n", t, title)
        } else {
            format!("# {}\n", title)
        };
        (fname, body)
    };
    let path = input.join(&filename);
    let _ = fs::create_dir_all(input);
    let _ = fs::write(&path, content);
    println!("{}", path.display());
    if edit {
        // try to open editor
        let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
        // If EDITOR is empty or not found, log error
        // Try to run editor
        let res = std::process::Command::new(&editor).arg(&path).status();
        match res {
            Ok(status) if status.success() => {},
            _ => {
                log_msg("ERROR", "marmite::content", &format!("Failed to open editor: {}", std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory")));
            }
        }
    }
}
