fn serve_site(output: &Path, bind: &str) -> Result<(), String> {
    use std::net::TcpListener;
    use std::io::{Read, Write};
    let listener = TcpListener::bind(bind).map_err(|e| e.to_string())?;
    for stream in listener.incoming() {
        if let Ok(mut s) = stream {
            let mut buf = [0u8; 8192];
            let n = s.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..n]).to_string();
            let mut path = "/";
            for line in req.lines() {
                if line.starts_with("GET ") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        path = parts[1];
                    }
                    break;
                }
            }
            // sanitize
            if path.contains("..") {
                let resp = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
                let _ = s.write_all(resp.as_bytes());
                continue;
            }
            let mut fpath = output.join(path.trim_start_matches('/'));
            if path == "/" || path.is_empty() {
                fpath = output.join("index.html");
            }
            if fpath.is_dir() {
                fpath = fpath.join("index.html");
            }
            if !fpath.exists() {
                // try 404.html
                let notfound = output.join("404.html");
                let body = fs::read(&notfound).unwrap_or_else(|_| b"Not found".to_vec());
                let header = format!("HTTP/1.1 404 Not Found\r\nContent-Length: {}\r\nContent-Type: text/html\r\n\r\n", body.len());
                let _ = s.write_all(header.as_bytes());
                let _ = s.write_all(&body);
            } else {
                let body = fs::read(&fpath).unwrap_or_default();
                let ctype = if fpath.extension().map(|e| e=="html").unwrap_or(false) {
                    "text/html"
                } else if fpath.extension().map(|e| e=="css").unwrap_or(false) {
                    "text/css"
                } else if fpath.extension().map(|e| e=="js").unwrap_or(false) {
                    "application/javascript"
                } else if fpath.extension().map(|e| e=="json").unwrap_or(false) {
                    "application/json"
                } else if fpath.extension().map(|e| e=="xml").unwrap_or(false) {
                    "application/xml"
                } else if fpath.extension().map(|e| e=="rss").unwrap_or(false) {
                    "application/rss+xml"
                } else {
                    "application/octet-stream"
                };
                let header = format!("HTTP/1.1 200 OK\r\nContent-Length: {}\r\nContent-Type: {}\r\n\r\n", body.len(), ctype);
                let _ = s.write_all(header.as_bytes());
                let _ = s.write_all(&body);
            }
        }
    }
    Ok(())
}

fn watch_loop(input: &Path, output: &Path, cfg: &Config) {
    use std::time::Duration;
    // collect initial mtimes
    fn collect_mtimes(dir: &Path) -> HashMap<PathBuf, std::time::SystemTime> {
        let mut map = HashMap::new();
        fn walk(d: &Path, m: &mut HashMap<PathBuf, std::time::SystemTime>) {
            if let Ok(entries) = fs::read_dir(d) {
                for e in entries.flatten() {
                    let p = e.path();
                    if let Ok(md) = e.metadata() {
                        if let Ok(mt) = md.modified() {
                            m.insert(p.clone(), mt);
                        }
                    }
                    if p.is_dir() {
                        walk(&p, m);
                    }
                }
            }
        }
        walk(dir, &mut map);
        map
    }
    let mut last = collect_mtimes(input);
    loop {
        std::thread::sleep(Duration::from_secs(1));
        let cur = collect_mtimes(input);
        if cur != last {
            log_msg("INFO", "marmite::site", "Changes detected, rebuilding...");
            let start = std::time::Instant::now();
            let _ = generate_site(input, output, cfg, start);
            last = cur;
        }
    }
}
